/**
 * @type {Map}
 * @private
 */
const $maps = [];
/**
 * @description プールされたMapがあればプールから、なければ新規作成して返却
 *              If there is a pooled Map, return it from the pool,
 *              otherwise create a new one and return it.
 *
 * @return {Map}
 * @method
 * @protected
 */
export const $getMap = () => {
    return $maps.pop() || new Map();
};
/**
 * @description 使用済みになったMapをプール
 *              Pool used Map.
 *
 * @param  {Map} map
 * @return {void}
 * @method
 * @protected
 */
export const $poolMap = (map) => {
    map.clear();
    $maps.push(map);
};
/**
 * @description プールされたArrayがあればプールから、なければ新規作成して返却
 *              If there is a pooled Array, return it from the pool,
 *              otherwise create a new one and return it.
 *
 * @param  {array} args
 * @return {array}
 * @method
 * @protected
 */
export const $getArray = (...args) => {
    const array = $arrays.pop() || [];
    if (args.length) {
        array.push(...args);
    }
    return array;
};
/**
 * @description 使用済みになったArrayをプール
 *              Pool used Array.
 *
 * @param  {array} array
 * @return {void}
 * @method
 * @protected
 */
export const $poolArray = (array) => {
    if (array.length) {
        array.length = 0;
    }
    $arrays.push(array);
};
/**
 * @description プールされたArrayがあればプールから、なければ新規作成して返却
 *              If there is a pooled Array, return it from the pool,
 *              otherwise create a new one and return it.
 *
 * @param  {number} x_min
 * @param  {number} y_min
 * @param  {number} x_max
 * @param  {number} y_max
 * @return {number[]}
 * @method
 * @protected
 */
export const $getBoundsArray = (x_min, y_min, x_max, y_max) => {
    const array = $boundsArrays.length
        ? $boundsArrays.pop()
        : new Float32Array(4);
    array[0] = x_min;
    array[1] = y_min;
    array[2] = x_max;
    array[3] = y_max;
    return array;
};
/**
 * @description 使用済みになったBoundsのArrayをプール
 *              Pool used Bounds Array.
 *
 * @param {Float32Array} array
 * @method
 * @protected
 */
export const $poolBoundsArray = (array) => {
    $boundsArrays.push(array);
};
/**
 * @param  {object} option
 * @return {void}
 * @method
 * @public
 */
export const $ajax = (option) => {
    // get or post
    let postData = null;
    switch (option.method.toUpperCase()) {
        case "GET":
            if (option.data) {
                const urls = option.url.split("?");
                urls[1] = urls.length === 1
                    ? option.data.toString()
                    : `${urls[1]}&${option.data.toString()}`;
                option.url = urls.join("?");
            }
            break;
        case "PUT":
        case "POST":
            if (option.data) {
                postData = option.data.toString();
            }
            break;
        default:
            break;
    }
    // start
    const xmlHttpRequest = new XMLHttpRequest();
    // init
    xmlHttpRequest.open(option.method, option.url, true);
    // set mimeType
    xmlHttpRequest.responseType = option.format;
    // use cookie
    xmlHttpRequest.withCredentials = option.withCredentials;
    // add event
    if (option.event) {
        const keys = Object.keys(option.event);
        for (let idx = 0; idx < keys.length; ++idx) {
            const name = keys[idx];
            // @ts-ignore
            xmlHttpRequest.addEventListener(name, option.event[name]);
        }
    }
    // set request header
    for (let idx = 0; idx < option.headers.length; ++idx) {
        const header = option.headers[idx];
        if (!header) {
            continue;
        }
        xmlHttpRequest.setRequestHeader(header.name, header.value);
    }
    xmlHttpRequest.send(postData);
};
/**
 * @description ヘッダー文字列を配列に変換
 *              Convert header string to array
 *
 * @param  {string} header
 * @return {array}
 * @method
 * @public
 */
export const $headerStringToArray = (header) => {
    const results = $getArray();
    if (header) {
        const headers = header.trim().split("\n");
        for (let idx = 0; idx < headers.length; ++idx) {
            const values = headers[idx].split(":");
            results.push({
                "name": values[0].trim(),
                "value": values[1].trim()
            });
        }
    }
    return results;
};
